   152  AllocResult HadesGC::HeapSegment::alloc(uint32_t sz) {
   153    assert(isSizeHeapAligned(sz) && "sz must be heap-aligned");
   154    assert(
   155        sz >= minAllocationSize() &&
   156        "Allocating too small of an object into old gen");
   157    if (bumpAllocMode_) {
   158      // No need to check for failure: if the bump alloc fails then the only free
   159      // space is beyond the level of the segment and is already considered.
   160      return bumpAlloc(sz);
   161    }
   162    // Need to track the previous entry in order to change the next pointer.
   163    FreelistCell **prevLoc = &freelistHead_;
   164    FreelistCell *cell = freelistHead_;
   165    // TODO: This algorithm is first-fit. The world of free-list allocation
   166    // algorithms is vast, and the best one can be explored later.
   167    while (true) {
   168      if (!cell) {
   169        // Free list exhausted, and nothing had enough space.
   170        return {nullptr, false};
   171      }
   172      assert(
   173          vmisa<FreelistCell>(cell) &&
   174          "Non-free-list cell found in the free list");
   175      assert(
   176          (!cell->next_ || cell->next_->isValid()) &&
   177          "Next pointer points to an invalid cell");
   178      // Check if the size is large enough that the cell could be split.
   179      if (cell->getAllocatedSize() >= sz + minAllocationSize()) {
   180        // Split the free cell. In order to avoid initializing soon-to-be-unused
   181        // values like the size and the next pointer, copy the return path here.
   182        *prevLoc = cell->split(*this, sz);
   183        allocatedBytes_ += sz;
   184        // Unpoison the memory so that the mutator can use it.
   185        __asan_unpoison_memory_region(cell + 1, sz - sizeof(FreelistCell));
   186        return {cell, true};
   187      } else if (cell->getAllocatedSize() == sz) {
   188        // Exact match, take it.
   189        break;
   190      }
   191      // Non-exact matches, or anything just barely too small to fit, will need
   192      // to find another block.
   193      // NOTE: This is due to restrictions on the minimum cell size to keep the
   194      // heap parseable, especially in debug mode. If this minimum size becomes
   195      // smaller (smaller header, size becomes part of it automatically, debug
   196      // magic field is handled differently), this decisions can be re-examined.
   197      // An example alternative is to make a special fixed-size cell that is only
   198      // as big as an empty GCCell. That alternative only works if the empty
   199      // is small enough to fit in any gap in the heap. That's not true in debug
   200      // modes currently.
   201      prevLoc = &cell->next_;
   202      cell = cell->next_;
   203    }
   204    assert(
   205        cell->getAllocatedSize() == sz &&
   206        "Cell found in free list should have exactly enough bytes to contain the "
   207        "allocation");
   208    assert(
   209        (!cell->next_ || cell->next_->isValid()) &&
   210        "Next pointer points to an invalid cell");
   211
   212    // Remove from free list.
   213    *prevLoc = cell->next_;
   214    // Track the number of allocated bytes in a segment.
   215    allocatedBytes_ += sz;
   216    // Unpoison the memory so that the mutator can use it.
   217    __asan_unpoison_memory_region(cell + 1, sz - sizeof(FreelistCell));
   218    // Could overwrite the VTable, but the allocator will write a new one in
   219    // anyway.
   220    return {cell, true};
   221  }
