   303  void HadesGC::HeapSegment::forAllObjs(CallbackFunction callback) {
   304    void *const stop = level();
   305    for (GCCell *cell = reinterpret_cast<GCCell *>(start()); cell < stop;
   306         cell = cell->nextCell()) {
   307      // Skip free-list entries.
   308      if (!vmisa<FreelistCell>(cell)) {
   309        callback(cell);
   310      }
   311    }
