  1498  void HadesGC::scanDirtyCards(EvacAcceptor &acceptor) {
  1499    SlotVisitor<EvacAcceptor> visitor{acceptor};
  1500    // The acceptors in this loop can grow the old gen by adding another
  1501    // segment, if there's not enough room to evac the YG objects discovered.
  1502    // Since segments are always placed at the end, we can use indices instead
  1503    // of iterators, which aren't invalidated. It's ok to not scan newly added
  1504    // segments, since they are going to be handled from the rest of YG
  1505    // collection.
  1506    const auto segEnd = oldGen_.size();
  1507    for (decltype(oldGen_.size()) i = 0; i < segEnd; ++i) {
  1508      HeapSegment &seg = *oldGen_[i];
  1509      const auto &cardTable = seg.cardTable();
  1510      // Use level instead of end in case the OG segment is still in bump alloc
  1511      // mode.
  1512      const char *const origSegLevel = seg.level();
  1513      size_t from = cardTable.addressToIndex(seg.start());
  1514      const size_t to = cardTable.addressToIndex(origSegLevel - 1) + 1;
  1515
  1516      while (const auto oiBegin = cardTable.findNextDirtyCard(from, to)) {
  1517        const auto iBegin = *oiBegin;
  1518
  1519        const auto oiEnd = cardTable.findNextCleanCard(iBegin, to);
  1520        const auto iEnd = oiEnd ? *oiEnd : to;
  1521
  1522        assert(
  1523            (iEnd == to || !cardTable.isCardForIndexDirty(iEnd)) &&
  1524            cardTable.isCardForIndexDirty(iEnd - 1) &&
  1525            "end should either be the end of the card table, or the first "
  1526            "non-dirty card after a sequence of dirty cards");
  1527        assert(iBegin < iEnd && "Indices must be apart by at least one");
  1528
  1529        const char *const begin = cardTable.indexToAddress(iBegin);
  1530        const char *const end = cardTable.indexToAddress(iEnd);
  1531        // Don't try to mark any cell past the original boundary of the segment.
  1532        const void *const boundary = std::min(end, origSegLevel);
  1533
  1534        // Use the object heads rather than the card table to discover the head
  1535        // of the object.
  1536        GCCell *const firstObj = seg.getCellHead(begin);
  1537        GCCell *obj = firstObj;
  1538        // Throughout this loop, objects are being marked which could promote
  1539        // other objects into the OG. Such objects might be promoted onto a dirty
  1540        // card, and be visited a second time. This is only a problem if the
  1541        // acceptor isn't idempotent. Luckily, EvacAcceptor happens to be
  1542        // idempotent, and so there's no correctness issue with visiting an object
  1543        // multiple times. If EvacAcceptor wasn't idempotent, we'd have to be able
  1544        // to identify objects promoted from YG in this loop, which would be
  1545        // expensive.
  1546
  1547        // Mark the first object with respect to the dirty card boundaries.
  1548        GCBase::markCellWithinRange(visitor, obj, obj->getVT(), this, begin, end);
  1549
  1550        // Mark the objects that are entirely contained within the dirty card
  1551        // boundaries.
  1552        for (GCCell *next = obj->nextCell(); next < boundary;
  1553             next = next->nextCell()) {
  1554          // Use a separate pointer for the loop condition so that the last
  1555          // object in range gets used with markCellWithinRange instead.
  1556          obj = next;
  1557          // Note that this object might be a FreelistCell. We could explicitly
  1558          // check for this, but since FreelistCell has an empty metadata this
  1559          // call ends up doing nothing anyway.
  1560          GCBase::markCell(visitor, obj, obj->getVT(), this);
  1561        }
  1562
  1563        // Mark the final object in the range with respect to the dirty card
  1564        // boundaries, as long as it does not coincide with the first object.
  1565        if (LLVM_LIKELY(obj != firstObj)) {
  1566          GCBase::markCellWithinRange(
  1567              visitor, obj, obj->getVT(), this, begin, end);
  1568        }
  1569
  1570        from = iEnd;
  1660  }
